import test from 'node:test';
import assert from 'node:assert/strict';
import { createIssuerEvidenceReadStore } from '../src/issuer-evidence-store.mjs';
const cfg={enabled:true,resourceAdmission:{status:'received'},cacheKey:'issuer-research/current.json',maximumCohortBytes:524288};
function namespace(response){const calls=[];return{calls,idFromName(name){calls.push(['id',name]);return 'same-id';},get(id){calls.push(['stub',id]);return{async fetch(request){calls.push(['fetch',request]);return typeof response==='function'?response(request):response;}};}};}
test('unadmitted issuer operation never obtains private binding authority',()=>{
  for(const config of [undefined,{...cfg,enabled:false},{...cfg,resourceAdmission:{status:'pending'}}])assert.equal(createIssuerEvidenceReadStore(null,config),undefined);
});
test('only configured logical key reaches the original singleton once and streams untouched bytes',async()=>{
  const response=new Response('{"é":true}',{headers:{'content-length':'11'}}),ns=namespace(response),store=createIssuerEvidenceReadStore(ns,cfg);
  await assert.rejects(store.get('opentask/auth'),TypeError);assert.deepEqual(ns.calls,[]);
  const found=await store.get(cfg.cacheKey);assert.equal(found.body,response.body);assert.equal(found.size,11);
  assert.equal(ns.calls.length,3);assert.deepEqual(ns.calls.slice(0,2),[['id','earning-loops'],['stub','same-id']]);
  const request=ns.calls[2][1],url=new URL(request.url);assert.equal(request.method,'GET');assert.equal(request.redirect,'manual');
  assert.equal(url.pathname,'/issuer-evidence');assert.deepEqual([...url.searchParams],[['key',cfg.cacheKey]]);
});
test('missing cohort is null; provider failures refuse with bounded public error',async()=>{
  assert.equal(await createIssuerEvidenceReadStore(namespace(new Response(null,{status:404})),cfg).get(cfg.cacheKey),null);
  for(const response of [new Response('private source error',{status:500}),...[301,302,303,307,308].map(status=>new Response(null,{status,headers:{location:'https://untrusted.invalid/refresh'}})),()=>{throw new Error('private token');}]){
    await assert.rejects(createIssuerEvidenceReadStore(namespace(response),cfg).get(cfg.cacheKey),error=>error.code==='issuer-revenue-unavailable'&&error.status===503&&error.retryable===true&&!error.message.includes('private'));
  }
});
test('malformed and overflow byte metadata cannot be passed to the paid selector',async()=>{
  for(const length of [null,'-1','01','1.5','NaN','9007199254740992','524289']){
    const headers=length===null?{}:{'content-length':length};
    await assert.rejects(createIssuerEvidenceReadStore(namespace(new Response('{}',{headers})),cfg).get(cfg.cacheKey),error=>error.code==='issuer-revenue-unavailable'&&error.status===503);
  }
});
